INSERT INTO `creature_loot_template` (`Entry`, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`, `MinCount`, `MaxCount`, `Comment`)
SELECT 60320, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`, `MinCount`, `MaxCount`, `Comment` FROM `creature_loot_template`
WHERE `Entry` = 1922 AND `QuestRequired` = 0 AND (`Reference` <> 0 OR (`Item` NOT IN (3164) AND `Item` NOT IN (SELECT `entry` FROM `item_template` WHERE `startquest` <> 0)));
UPDATE `creature_template` f JOIN `creature_template` w ON w.`entry` = 1922 SET f.`lootid` = 60320, f.`skinloot` = w.`skinloot` WHERE f.`entry` = 60320;
